279:   record: DeepReadonly<LocalAcceptanceRecord>,
280:   event: DeepReadonly<LocalAcceptanceLifecycleEvent>,
281:   previousState: AcceptanceLifecycleState,
282:   ctx: TemporalContext,
283:   policy?: LifecyclePolicy,
284: ): Result<LifecycleTransition> {
285:   const validRecord = createLocalAcceptanceRecord(record);
286:   if (!validRecord.ok) return validRecord;
287:   const validEvent = createLocalAcceptanceLifecycleEvent(event);
288:   if (!validEvent.ok) return validEvent;
289:   if (!isState(previousState)) {
290:     return invalid('previousState', 'unknown lifecycle state');
291:   }
292:   if (validEvent.value.acceptance_id !== validRecord.value.acceptance_id) {
293:     return policyMechanism('Lifecycle event does not refer to the supplied acceptance record');
294:   }
295: 
296:   const validatedBasis = validateTemporalFieldRef(ctx.basis);
297:   if (!validatedBasis.ok) return validatedBasis;
298:   const declaredAt = declaredAtFor(ctx, validatedBasis.value);
299: 
300:   if (policy === undefined) {
301:     return { ok: true, value: { status: 'POLICY_REQUIRED' } };
302:   }
303:   if (typeof policy.allowsTransition !== 'function') {
304:     return policyMechanism('LifecyclePolicy.allowsTransition is required');
305:   }
306: 
307:   let allowed: boolean;
308:   try {
309:     allowed = policy.allowsTransition({
310:       record: validRecord.value,
311:       event: validEvent.value,
312:       previousState,
313:       basis: validatedBasis.value,
314:       ...(declaredAt === undefined ? {} : { declaredAt }),
315:       effectiveAt: validEvent.value.effective_at,
316:       ctx,
317:     });
318:   } catch (error) {
319:     return policyMechanism(
320:       `LifecyclePolicy.allowsTransition failed: ${error instanceof Error ? error.message : String(error)}`,
321:     );
322:   }
323:   if (typeof allowed !== 'boolean') {
324:     return policyMechanism('LifecyclePolicy.allowsTransition must return a boolean');
325:   }
326:   if (!allowed) {
327:     return {
328:       ok: true,
329:       value: {
330:         status: 'REJECTED',
331:         previousState,
332:         proposedState: validEvent.value.new_state,
333:       },
334:     };
335:   }
336:   return { ok: true, value: { status: 'TRANSITIONED', state: validEvent.value.new_state } };
