339: /**
340:  * Contextual applicability query. Lifecycle state is considered only through
341:  * the supplied policy; ACTIVE is not implicitly applicable.
342:  */
343: export function isAcceptable(
344:   record: DeepReadonly<LocalAcceptanceRecord>,
345:   state: AcceptanceLifecycleState,
346:   query: AcceptanceQuery,
347:   ctx: TemporalContext,
348:   policy?: AcceptanceApplicabilityPolicy,
349: ): Result<AcceptanceApplicability> {
350:   const validRecord = createLocalAcceptanceRecord(record);
351:   if (!validRecord.ok) return validRecord;
352:   if (!isState(state)) {
353:     return invalid('state', 'unknown lifecycle state');
354:   }
355: 
356:   if (validRecord.value.decision === 'REJECTED') {
357:     return { ok: true, value: { status: 'NOT_APPLICABLE', reason: 'DECISION_REJECTED' } };
358:   }
359:   if (validRecord.value.accepting_domain !== query.accepting_domain) {
360:     return { ok: true, value: { status: 'NOT_APPLICABLE', reason: 'DOMAIN_MISMATCH' } };
361:   }
362:   if (validRecord.value.context_scope !== query.context_scope) {
363:     return { ok: true, value: { status: 'NOT_APPLICABLE', reason: 'CONTEXT_MISMATCH' } };
364:   }
365:   if (validRecord.value.subject_version_id !== query.subject_version_id) {
366:     return { ok: true, value: { status: 'NOT_APPLICABLE', reason: 'SUBJECT_MISMATCH' } };
367:   }
368: 
369:   const validatedBasis = validateTemporalFieldRef(ctx.basis);
370:   if (!validatedBasis.ok) return validatedBasis;
371:   const declaredAt = declaredAtFor(ctx, validatedBasis.value);
372: 
373:   if (policy === undefined) {
374:     return { ok: true, value: { status: 'POLICY_REQUIRED' } };
375:   }
376:   if (typeof policy.isApplicable !== 'function') {
377:     return policyMechanism('AcceptanceApplicabilityPolicy.isApplicable is required');
378:   }
379: 
380:   let applicable: boolean;
381:   try {
382:     applicable = policy.isApplicable({
383:       record: validRecord.value,
384:       state,
385:       query,
386:       basis: validatedBasis.value,
387:       ...(declaredAt === undefined ? {} : { declaredAt }),
388:       ctx,
389:     });
390:   } catch (error) {
391:     return policyMechanism(
392:       `AcceptanceApplicabilityPolicy.isApplicable failed: ${error instanceof Error ? error.message : String(error)}`,
393:     );
394:   }
395:   if (typeof applicable !== 'boolean') {
396:     return policyMechanism('AcceptanceApplicabilityPolicy.isApplicable must return a boolean');
397:   }
398:   return applicable
399:     ? { ok: true, value: { status: 'APPLICABLE' } }
400:     : { ok: true, value: { status: 'NOT_APPLICABLE', reason: 'POLICY_REJECTED' } };
