322: /** Structural coverage counters used to report what the generator actually produced. */
323: export function shapeStats(graph: LineageGraph): ShapeStats {
324:   const parentsByChild = new Map<string, { relation: string; parent: string }[]>();
325:   for (const edge of graph.edges) {
326:     const list = parentsByChild.get(String(edge.child)) ?? [];
327:     list.push({ relation: edge.relation, parent: String(edge.parent) });
328:     parentsByChild.set(String(edge.child), list);
329:   }
330: 
331:   let mergeNodes = 0;
332:   let mixedRelationNodes = 0;
333:   let closureOnlyBranches = 0;
334: 
335:   for (const parents of parentsByChild.values()) {
336:     if (!parents.some((parent) => parent.relation === 'MERGED_FROM')) {
337:       continue;
338:     }
339:     mergeNodes += 1;
340:     if (new Set(parents.map((parent) => parent.relation)).size > 1) {
341:       mixedRelationNodes += 1;
342:     }
343:     for (const parent of parents) {
344:       if ((parentsByChild.get(parent.parent) ?? []).length > 0) {
345:         closureOnlyBranches += 1;
346:       }
347:     }
348:   }
