24: function visitModule(filePath: string, exported: Set<string>, visited: Set<string>): void {
25:   if (visited.has(filePath)) {
26:     return;
27:   }
28:   visited.add(filePath);
29:   const source = ts.createSourceFile(filePath, readFileSync(filePath, 'utf8'), ts.ScriptTarget.Latest, true);
30: 
31:   for (const statement of source.statements) {
32:     collectDeclaration(statement, exported);
33:     if (ts.isExportAssignment(statement)) {
34:       exported.add('default');
35:     }
36:     if (ts.isExportDeclaration(statement)) {
37:       collectExportDeclaration(statement, filePath, exported, visited);
38:     }
39:   }
40: }
