42: function collectExportDeclaration(
43:   statement: ts.ExportDeclaration,
44:   filePath: string,
45:   exported: Set<string>,
46:   visited: Set<string>,
47: ): void {
48:   const target = moduleTarget(statement, filePath);
49: 
50:   if (statement.exportClause === undefined) {
51:     if (target !== undefined) {
52:       visitModule(target, exported, visited);
53:     }
54:     return;
55:   }
56: 
57:   if (ts.isNamedExports(statement.exportClause)) {
58:     for (const element of statement.exportClause.elements) {
59:       exported.add(element.name.text);
60:       if (element.propertyName !== undefined) {
61:         exported.add(element.propertyName.text);
62:       }
63:     }
64:     return;
65:   }
66: 
67:   if (ts.isNamespaceExport(statement.exportClause)) {
