121: export function signaturePolicy(overrides: Partial<SignatureTemporalPolicy> = {}): SignatureTemporalPolicy {
122:   return {
123:     acceptCompromiseTime: () => true,
124:     evaluateFutureAuthorization: (): FutureAuthorizationOutcome => 'NOT_AUTHORIZABLE',
125:     ...overrides,
126:   };
127: }
