130: const defaultBinding = identityBinding();
131: const defaultRevocation = revocationFixture();
132: const defaultSignedRef = signedAtSubjectRef(defaultCredential, defaultBinding);
133: const defaultCompromiseRef = revocationSubjectRef(defaultRevocation);
134: 
135: export function contextFor(
136:   options: {
137:     readonly signed?: TemporalTrustInput | 'missing';
138:     readonly compromise?: TemporalTrustInput | 'missing';
139:     readonly signedValue?: number;
140:     readonly compromiseValue?: number;
141:     readonly signedKey?: string;
142:     readonly compromiseKey?: string;
143:   } = {},
144: ): TemporalContext {
145:   const signedValue = options.signedValue ?? SIGNED_AT;
146:   const compromiseValue = options.compromiseValue ?? COMPROMISE_AT;
147:   const entries: Record<string, Record<string, TemporalTrustInput>> = {};
148: 
149:   if (options.signed !== 'missing') {
150:     const key = options.signedKey ?? defaultSignedRef;
151:     entries[key] = {
152:       SIGNED_AT: options.signed ?? trustInput({ field: 'SIGNED_AT', subject: key, value: signedValue, trusted: true }),
153:     };
154:   }
155:   if (options.compromise !== 'missing') {
156:     const key = options.compromiseKey ?? defaultCompromiseRef;
157:     entries[key] = {
158:       compromise_effective_at:
159:         options.compromise ??
