161:           field: 'compromise_effective_at',
162:           subject: key,
163:           value: compromiseValue,
164:           trusted: true,
165:         }),
166:     };
167:   }
168: 
169:   return trustContext(entries, { SIGNED_AT: signedValue, compromise_effective_at: compromiseValue });
170: }
