309: function closesSupersessionCycle(
310:   existing: readonly DeepReadonly<ContinuityAssessment>[],
311:   successor: DeepReadonly<ContinuityAssessment>,
312: ): boolean {
313:   const links = new Map<AssessmentID, AssessmentID | undefined>();
314:   for (const assessment of existing) {
315:     links.set(assessment.assessment_id, assessment.supersedes_assessment_id);
316:   }
317:   links.set(successor.assessment_id, successor.supersedes_assessment_id);
318: 
319:   const seen = new Set<AssessmentID>();
320:   let current: AssessmentID | undefined = successor.assessment_id;
321:   while (current !== undefined) {
322:     if (seen.has(current)) {
323:       return true;
324:     }
325:     seen.add(current);
326:     current = links.get(current);
327:   }
328:   return false;
329: }
