331: /**
332:  * Registers a successor in a copy-on-write assessment list. A supersession
333:  * cycle is a normative rejection (`CYCLE_DETECTED`); existing records are never
334:  * mutated and there is no latest-wins selection.
335:  */
336: export function registerAssessment(
337:   existing: readonly DeepReadonly<ContinuityAssessment>[],
338:   successor: ContinuityAssessment,
339: ): Result<readonly DeepReadonly<ContinuityAssessment>[]> {
340:   const copiedExisting = deepCopy(existing);
341:   if (!copiedExisting.ok) {
342:     return copiedExisting;
343:   }
344:   const registeredExisting = deepFreeze(copiedExisting.value);
345: 
346:   const copied = deepCopy(successor);
347:   if (!copied.ok) {
348:     return copied;
349:   }
350:   const registered = deepFreeze(copied.value);
351: 
352:   if (registered.supersedes_assessment_id === registered.assessment_id) {
353:     return cycleRejection(registered.assessment_id);
354:   }
355: 
356:   if (registeredExisting.some((item) => item.assessment_id === registered.assessment_id)) {
357:     return mechanismRejection(`Duplicate assessment_id: ${registered.assessment_id}`);
358:   }
359: 
360:   const predecessor = registered.supersedes_assessment_id;
361:   if (predecessor !== undefined && !registeredExisting.some((item) => item.assessment_id === predecessor)) {
362:     return mechanismRejection(`Unknown supersedes_assessment_id: ${predecessor}`);
363:   }
364: 
365:   if (closesSupersessionCycle(registeredExisting, registered)) {
366:     return cycleRejection(registered.assessment_id);
367:   }
368: 
369:   return { ok: true, value: Object.freeze([...registeredExisting, registered]) };
370: }

