341:   const versions = registry.versions();
342:   const nodes = [...new Set(versions.map((version) => version.id))].sort(compareStrings);
343:   const nodeSet = new Set(nodes);
344:   const edges = collectEdges(versions);
345:   const unresolvedParents = collectUnresolvedParents(nodeSet, edges);
346:   const adjacency = buildAdjacency(nodes, edges);
347:   const cycles = stronglyConnectedComponents(nodes, adjacency).filter((component) =>
348:     isCyclicComponent(component, adjacency),
349:   );
350: 
351:   return deepFreeze({ nodes, edges, unresolvedParents, cycles }) as LineageGraph;
352: }

