241:       if (frame.next >= parents.length) {
242:         order.push(frame.node);
243:         stack.pop();
244:         continue;
245:       }
246: 
247:       const parent = parents[frame.next];
248:       frame.next += 1;
249:       if (!visited.has(parent) && adjacency.has(parent)) {
250:         visited.add(parent);
251:         stack.push({ node: parent, next: 0 });
252:       }
253:     }
254:   }
