259: function reverseAdjacency(
260:   nodes: readonly IdentityVersionID[],
261:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
262: ): Map<IdentityVersionID, IdentityVersionID[]> {
263:   const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
264:   for (const node of nodes) {
265:     reverse.set(node, []);
266:   }
267:   for (const [child, parents] of adjacency) {
268:     for (const parent of parents) {
269:       reverse.get(parent)?.push(child);
270:     }
271:   }
272:   for (const children of reverse.values()) {
273:     children.sort(compareStrings);
274:   }
275:   return reverse;
276: }
