278: function stronglyConnectedComponents(
279:   nodes: readonly IdentityVersionID[],
280:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
281: ): IdentityVersionID[][] {
282:   const order = finishOrder(nodes, adjacency);
283:   const reverse = reverseAdjacency(nodes, adjacency);
284:   const assigned = new Set<IdentityVersionID>();
285:   const components: IdentityVersionID[][] = [];
286: 
287:   for (let index = order.length - 1; index >= 0; index -= 1) {
288:     const start = order[index];
289:     if (assigned.has(start)) {
290:       continue;
291:     }
292: 
293:     const component: IdentityVersionID[] = [];
294:     const stack: IdentityVersionID[] = [start];
295:     assigned.add(start);
296: 
297:     while (stack.length > 0) {
298:       const node = stack.pop();
299:       if (node === undefined) {
300:         break;
301:       }
302:       component.push(node);
303:       for (const child of reverse.get(node) ?? []) {
304:         if (!assigned.has(child)) {
305:           assigned.add(child);
306:           stack.push(child);
307:         }
308:       }
309:     }
310: 
311:     component.sort(compareStrings);
312:     components.push(component);
313:   }
314: 
315:   components.sort((a, b) => compareStrings(a[0], b[0]));
316:   return components;
317: }
318: 
319: function isCyclicComponent(
320:   component: readonly IdentityVersionID[],
321:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
322: ): boolean {
323:   if (component.length > 1) {
324:     return true;
325:   }
326:   const node = component[0];
327:   return (adjacency.get(node) ?? []).includes(node);
328: }
