330: /**
331:  * Builds an immutable lineage graph snapshot from a Registry.
332:  *
333:  * Declared edges are preserved exactly, including duplicates and references to
334:  * parents that are not registered yet. Unresolved parents are grouped by child
335:  * and deduplicated for diagnostics only. Cycles are reported as sorted strongly
336:  * connected components (a self-loop is a one-node component); they do not
337:  * remove nodes or edges. `CYCLE_DETECTED` belongs to the assessment boundary of
338:  * a later traversal task and is not emitted here.
339:  */
340: export function buildLineageGraph(registry: Registry): LineageGraph {
341:   const versions = registry.versions();
342:   const nodes = [...new Set(versions.map((version) => version.id))].sort(compareStrings);
343:   const nodeSet = new Set(nodes);
344:   const edges = collectEdges(versions);
345:   const unresolvedParents = collectUnresolvedParents(nodeSet, edges);
346:   const adjacency = buildAdjacency(nodes, edges);
347:   const cycles = stronglyConnectedComponents(nodes, adjacency).filter((component) =>
348:     isCyclicComponent(component, adjacency),
349:   );
350: 
351:   return deepFreeze({ nodes, edges, unresolvedParents, cycles }) as LineageGraph;
352: }

