function mapHasCycle(links: ReadonlyMap<AssessmentID, AssessmentID | undefined>, start: AssessmentID): boolean {
  const seen = new Set<AssessmentID>();
  let current: AssessmentID | undefined = start;
  while (current !== undefined) {
