Then `validateContinuityAssessment` does:
```ts
const json = validateJsonValue(value);
if (!json.ok) return json;
if (!isJsonObject(json.value)) return mechanismRejection(...);
const unknown = firstUnknownField(json.value);
if (unknown !== undefined) return ...;
const header = readHeader(json.value); if (!header.ok) return header;
const parents = readParents(json.value, header.value.subject); if (!parents.ok) return parents;
const relation = readRelation(json.value); if (!relation.ok) return relation;
