527	function directParentBranches(graph: LineageGraph, child: IdentityVersionID): EdgeRef[] {
528	  const branches = new Map<string, EdgeRef>();
529	  for (const candidate of graph.edges) {
530	    if (candidate.child !== child) {
531	      continue;
532	    }
533	    const branch = edgeRef(candidate);
534	    branches.set(`${String(branch.parent)}\u0000${branch.relation}`, branch);
535	  }
536	  return [...branches.values()].sort(
537	    (a, b) => compareStrings(a.parent, b.parent) || compareStrings(a.relation, b.relation),
538	  );
539	}
540	
541	function evaluateClosureBranch(
542	  branch: EdgeRef,
543	  assessments: readonly ContinuityAssessment[],
544	  requirement: ContinuityAssuranceRequirement,
545	  policy: Policy,
546	  ctx: TemporalContext,
547	): Result<MergeClosureBranchFailure | undefined> {
548	  const outcome = evaluateEdgeAssurance(branch, assessments, requirement, policy, ctx);
549	  if (!outcome.ok) {
550	    return outcome;
551	  }
552	
553	  if (outcome.value.status === 'SATISFIED') {
554	    return { ok: true, value: undefined };
555	  }
556	  if (outcome.value.status === 'NO_APPLICABLE_ASSESSMENT') {
557	    return { ok: true, value: { branch, reason: 'NO_APPLICABLE_ASSESSMENT' } };
558	  }
559	  if (outcome.value.status === 'UNSATISFIED') {
560	    return {
561	      ok: true,
562	      value: {
563	        branch,
564	        reason: 'ASSURANCE_UNSATISFIED',
565	        missing: outcome.value.missing,
566	        disallowed: outcome.value.disallowed,
567	      },
568	    };
569	  }
570	  return {
571	    ok: true,
572	    value: { branch, reason: 'CONTESTED', contestedClaims: outcome.value.contestedClaims },
573	  };
574	}
