580	function collectBranchFailure(
581	  failures: Map<string, MergeClosureBranchFailure>,
582	  edge: EdgeRef,
583	  branch: EdgeRef,
584	  assessments: readonly ContinuityAssessment[],
585	  requirement: ContinuityAssuranceRequirement,
586	  policy: Policy,
587	  ctx: TemporalContext,
588	): Result<undefined> {
589	  if (branch.parent === edge.parent && branch.relation === edge.relation) {
590	    return { ok: true, value: undefined };
591	  }
592	  const key = closureBranchKey(branch);
593	  if (failures.has(key)) {
594	    return { ok: true, value: undefined };
595	  }
596	
597	  const failure = evaluateClosureBranch(branch, assessments, requirement, policy, ctx);
598	  if (!failure.ok) {
599	    return failure;
600	  }
601	  if (failure.value !== undefined) {
602	    failures.set(key, failure.value);
603	  }
604	  return { ok: true, value: undefined };
605	}
