import re, pathlib
root = pathlib.Path('.')
files = list((root/'docs/audits/2026-10-31-core-001-task-18/decision-packages/T18-09A-assurance-semantics').glob('*.md'))
pat = re.compile(r'((?:docs|src|tests)/[A-Za-z0-9_./-]+\.(?:md|ts)):(\d+)')
missing = []
for f in files:
    text = f.read_text()
    for m in pat.finditer(text):
        path, line = m.group(1), int(m.group(2))
        p = root/path
        if not p.exists():
            missing.append((f.name, path, line, 'missing file'))
        else:
            n = len(p.read_text().splitlines())
            if line > n:
                missing.append((f.name, path, line, f'out of range ({n})'))
print('checked files:', len(files))
if missing:
    for item in missing: print('BAD', item)
else:
    print('all full-path line references resolve')
